#!/usr/bin/env python3
"""daemon-scan.py — candidate scan for the merge daemon in ONE GraphQL call (meta tool, 2026-09-09).
Prints one line per candidate: PR:N:BRANCH:SLUG:MODE:HEAD, where a candidate is an open PR whose head commit carries
ci/summary=success and review/summary=success statuses and whose latest local review for that head has no unresolved
ledger line (MODE clean), or whose number is in the adjudication list (MODE adj) with at least CI success.
Usage: daemon-scan.py [adj-list-file]   (stderr carries diagnostics; exit 1 on API failure)."""
import json, os, re, subprocess, sys

ADJ = set()
if len(sys.argv) > 1 and os.path.exists(sys.argv[1]):
    ADJ = set(open(sys.argv[1]).read().split())
Q = '''query { repository(owner:"Dengnifer", name:"MIPStarRE-A") { pullRequests(states:OPEN, first:100, orderBy:{field:UPDATED_AT, direction:DESC}) { nodes {
  number headRefName headRefOid
  commits(last:1) { nodes { commit { status { contexts { context state } } } } }
  reviews(last:8) { nodes { body } } } } } }'''
try:
    out = subprocess.run(["gh", "api", "graphql", "-f", f"query={Q}"], capture_output=True, text=True, timeout=120)
except subprocess.TimeoutExpired:
    print("scan: graphql timeout", file=sys.stderr); sys.exit(1)
if out.returncode != 0:
    print("scan: graphql failed: " + out.stderr[:200], file=sys.stderr); sys.exit(1)
nodes = json.loads(out.stdout)["data"]["repository"]["pullRequests"]["nodes"]
n_cand = 0
for pr in nodes:
    num = str(pr["number"]); br = pr["headRefName"]; head = pr["headRefOid"]
    m = re.match(r"^issue-0*([0-9]+)-(.*)$", br)
    if not m:
        continue
    n, slug = m.group(1), m.group(2)
    ctx = {}
    for c in pr["commits"]["nodes"]:
        st = (c["commit"] or {}).get("status") or {}
        for x in st.get("contexts") or []:
            ctx[x["context"]] = x["state"]
    ci = ctx.get("local-ci/summary") == "SUCCESS"
    rv = ctx.get("local-review/summary") == "SUCCESS"
    if not ci:
        continue
    clean = False
    if rv:
        bodies = [r["body"] or "" for r in pr["reviews"]["nodes"] if "mipstarre-review" in (r["body"] or "") and f"head={head}" in (r["body"] or "")]
        if bodies:
            unresolved = len(re.findall(r"^- \[ \]", bodies[-1], re.M))
            clean = unresolved == 0
    if clean:
        print(f"{num}:{n}:{br}:{slug}:clean:{head}"); n_cand += 1
    elif num in ADJ:
        print(f"{num}:{n}:{br}:{slug}:adj:{head}"); n_cand += 1
print(f"scan: {len(nodes)} open PRs, {n_cand} candidates", file=sys.stderr)
